-- Comentarios do CTN, lote 4 (arts. 67 a 100). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='ctn' and numero between 67 and 100 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(67,'','Imposto sobre transportes e comunicações: destinação da receita','A receita líquida do imposto destina-se à formação de reservas monetárias, na forma da lei.'),
(68,'','Imposto sobre transportes e comunicações: fato gerador','O imposto, de competência da União, sobre serviços de transportes e comunicações tem como fato gerador a prestação do serviço de transporte, por qualquer via, de pessoas, bens, mercadorias ou valores, salvo quando o trajeto se contenha inteiramente no território de um mesmo Município (inciso I), e a prestação do serviço de comunicações, assim se entendendo a transmissão e o recebimento, por qualquer processo, de mensagens escritas, faladas ou visuais, salvo quando os pontos de transmissão e de recebimento se situem no território de um mesmo Município e a mensagem em curso não possa ser captada fora desse território (inciso II).'),
(69,'','Imposto sobre transportes e comunicações: base de cálculo','A base de cálculo do imposto é o preço do serviço.'),
(70,'','Imposto sobre transportes e comunicações: contribuinte','Contribuinte do imposto é o prestador do serviço.'),
(74,'','Imposto sobre combustíveis, lubrificantes, energia elétrica e minerais: fato gerador','O imposto, de competência da União, sobre operações relativas a combustíveis, lubrificantes, energia elétrica e minerais do País tem como fato gerador a produção, como definida no art. 46 e seu parágrafo único (inciso I); a importação, como definida no art. 19 (inciso II); a circulação, como definida no art. 52 (inciso III); a distribuição, assim entendida a colocação do produto no estabelecimento consumidor ou em local de venda ao público (inciso IV); e o consumo, assim entendida a venda do produto ao público (inciso V). O § 1º considera a energia elétrica produto industrializado para os efeitos do imposto. O § 2º dispõe que o imposto incide uma só vez sobre uma das operações previstas em cada inciso, como dispuser a lei, e exclui quaisquer outros tributos, sejam quais forem sua natureza ou competência, incidentes sobre aquelas operações.'),
(75,'','Imposto sobre combustíveis, energia e minerais: remissão a outros impostos','A lei observará o disposto no Título relativamente ao imposto sobre produtos industrializados, quando a incidência seja sobre a produção ou sobre o consumo (inciso I); ao imposto sobre a importação, quando a incidência seja sobre essa operação (inciso II); e ao imposto sobre operações relativas à circulação de mercadorias, quando a incidência seja sobre a distribuição (inciso III).'),
(76,'','Impostos extraordinários de guerra','Na iminência ou no caso de guerra externa, a União pode instituir, temporariamente, impostos extraordinários compreendidos ou não entre os referidos no CTN, suprimidos, gradativamente, no prazo máximo de cinco anos, contados da celebração da paz.'),
(77,'','Taxas: fato gerador e limites','As taxas cobradas pela União, pelos Estados, pelo Distrito Federal ou pelos Municípios, no âmbito de suas respectivas atribuições, têm como fato gerador o exercício regular do poder de polícia, ou a utilização, efetiva ou potencial, de serviço público específico e divisível, prestado ao contribuinte ou posto à sua disposição. O parágrafo único dispõe que a taxa não pode ter base de cálculo ou fato gerador idênticos aos que correspondam a imposto nem ser calculada em função do capital das empresas; o texto traz a anotação "Vide Ato Complementar nº 34, de 1967".'),
(78,'','Taxas: poder de polícia','Considera-se poder de polícia a atividade da administração pública que, limitando ou disciplinando direito, interesse ou liberdade, regula a prática de ato ou abstenção de fato, em razão de interesse público concernente à segurança, à higiene, à ordem, aos costumes, à disciplina da produção e do mercado, ao exercício de atividades econômicas dependentes de concessão ou autorização do Poder Público, à tranquilidade pública ou ao respeito à propriedade e aos direitos individuais ou coletivos. O parágrafo único considera regular o exercício do poder de polícia quando desempenhado pelo órgão competente nos limites da lei aplicável, com observância do processo legal e, tratando-se de atividade que a lei tenha como discricionária, sem abuso ou desvio de poder.'),
(79,'','Taxas: serviços públicos utilizados, específicos e divisíveis','Os serviços públicos a que se refere o art. 77 consideram-se utilizados pelo contribuinte efetivamente, quando por ele usufruídos a qualquer título (inciso I, alínea a), ou potencialmente, quando, sendo de utilização compulsória, sejam postos à sua disposição mediante atividade administrativa em efetivo funcionamento (alínea b); específicos, quando possam ser destacados em unidades autônomas de intervenção, de utilidade, ou de necessidades públicas (inciso II); e divisíveis, quando suscetíveis de utilização, separadamente, por parte de cada um dos seus usuários (inciso III).'),
(80,'','Taxas: âmbito de atribuições de cada ente','Para efeito de instituição e cobrança de taxas, consideram-se compreendidas no âmbito das atribuições da União, dos Estados, do Distrito Federal ou dos Municípios aquelas que, segundo a Constituição Federal, as Constituições dos Estados, as Leis Orgânicas do Distrito Federal e dos Municípios e a legislação com elas compatível, competem a cada uma dessas pessoas de direito público.'),
(81,'','Contribuição de melhoria: instituição e limites','A contribuição de melhoria cobrada pela União, pelos Estados, pelo Distrito Federal ou pelos Municípios, no âmbito de suas respectivas atribuições, é instituída para fazer face ao custo de obras públicas de que decorra valorização imobiliária, tendo como limite total a despesa realizada e como limite individual o acréscimo de valor que da obra resultar para cada imóvel beneficiado.'),
(82,'','Contribuição de melhoria: requisitos mínimos da lei','A lei relativa à contribuição de melhoria observará como requisitos mínimos: publicação prévia do memorial descritivo do projeto, do orçamento do custo da obra, da determinação da parcela do custo da obra a ser financiada pela contribuição, da delimitação da zona beneficiada e da determinação do fator de absorção do benefício da valorização (inciso I, alíneas a a e); fixação de prazo não inferior a 30 (trinta) dias para impugnação pelos interessados de qualquer desses elementos (inciso II); e regulamentação do processo administrativo de instrução e julgamento da impugnação, sem prejuízo da sua apreciação judicial (inciso III). O § 1º dispõe que a contribuição relativa a cada imóvel será determinada pelo rateio da parcela do custo da obra a que se refere a alínea c do inciso I pelos imóveis situados na zona beneficiada, em função dos respectivos fatores individuais de valorização. O § 2º dispõe que, por ocasião do lançamento, cada contribuinte deverá ser notificado do montante da contribuição, da forma e dos prazos de seu pagamento e dos elementos que integraram o respectivo cálculo.'),
(82,'Art. 82-A','Contribuição para iluminação pública e monitoramento','Os Municípios e o Distrito Federal poderão instituir contribuição, na forma das respectivas leis, para o custeio, a expansão e a melhoria do serviço de iluminação pública e de sistemas de monitoramento para segurança e preservação de logradouros públicos, observado o disposto nos incisos I e III do caput do art. 150 da Constituição Federal (Lei Complementar n. 227, de 2026). O § 1º define, para esses fins, o custeio, a expansão e a melhoria do serviço de iluminação pública (inciso I) e dos sistemas de monitoramento para segurança e preservação de logradouros públicos (inciso II), nos termos dos incisos. O § 2º faculta a cobrança da contribuição na fatura de consumo de energia elétrica.'),
(83,'','Participação de Estados e Municípios em tributos federais mediante convênio','Sem prejuízo das demais disposições do Título, os Estados e Municípios que celebrem com a União convênios destinados a assegurar ampla e eficiente coordenação dos respectivos programas de investimentos e serviços públicos, especialmente no campo da política tributária, poderão participar de até 10% (dez por cento) da arrecadação efetuada, nos respectivos territórios, proveniente do imposto referido no art. 43, incidente sobre o rendimento das pessoas físicas, e no art. 46, excluído o incidente sobre o fumo e bebidas alcoólicas. O parágrafo único dispõe que o processo das distribuições será regulado nos convênios nele referidos.'),
(84,'','Encargo de arrecadar impostos de outro ente','A lei federal pode cometer aos Estados, ao Distrito Federal ou aos Municípios o encargo de arrecadar os impostos de competência da União cujo produto lhes seja distribuído no todo ou em parte. O parágrafo único aplica o disposto à arrecadação dos impostos de competência dos Estados, cujo produto estes venham a distribuir, no todo ou em parte, aos respectivos Municípios.'),
(85,'','Distribuição de receitas pela União','Serão distribuídos pela União aos Municípios da localização dos imóveis o produto da arrecadação do imposto a que se refere o art. 29 (inciso I) e aos Estados, ao Distrito Federal e aos Municípios o produto da arrecadação, na fonte, do imposto a que se refere o art. 43, incidente sobre a renda das obrigações de sua dívida pública e sobre os proventos dos seus servidores e dos de suas autarquias (inciso II). O § 1º determina que as autoridades arrecadadoras façam a entrega das importâncias, independentemente de ordem das autoridades superiores e sob pena de demissão, à medida que forem arrecadadas, em prazo não superior a 30 (trinta) dias, a contar da data de cada recolhimento. O § 2º dispõe que a lei poderá autorizar Estados, Distrito Federal e Municípios a incorporar definitivamente à sua receita o produto da arrecadação do imposto a que se refere o inciso II, estipulando as obrigações acessórias a serem cumpridas por aqueles. O § 3º consta como suspenso na fonte (Resolução do Senado Federal n. 337, de 1983) e está registrado como não vigente.'),
(90,'','Fundo de Participação: fator do inverso da renda per capita','O fator representativo do inverso da renda per capita, a que se refere o inciso II do art. 88, é estabelecido por tabela que associa faixas do inverso do índice relativo à renda per capita da entidade participante a fatores que vão de 0,4 (até 0,0045) a 2,5 (acima de 0,220), nos termos da tabela do artigo. O parágrafo único dispõe que, para esses efeitos, determina-se o índice relativo à renda per capita de cada entidade participante tomando-se como 100 (cem) a renda per capita média do País.'),
(91,'','Fundo de Participação dos Municípios: repartição','Do Fundo de Participação dos Municípios a que se refere o art. 86 são atribuídos 10% (dez por cento) aos Municípios das Capitais dos Estados (inciso I) e 90% (noventa por cento) aos demais Municípios do País (inciso II). O § 1º trata da distribuição da parcela do inciso I, proporcional a um coeficiente individual de participação resultante do produto de um fator representativo da população (alínea a, nos termos da tabela do dispositivo) e do fator representativo do inverso da renda per capita do respectivo Estado, conforme o art. 90 (alínea b). O § 2º trata da distribuição da parcela do inciso II por coeficiente individual de participação, determinado por faixas de população (alíneas a a e, nos termos da tabela do dispositivo). O § 3º dispõe que, para os efeitos do artigo, consideram-se os municípios regularmente instalados, fazendo-se a revisão das quotas anualmente, a partir de 1989, com base em dados oficiais de população produzidos pela Fundação Instituto Brasileiro de Geografia e Estatística (IBGE). Os §§ 4º e 5º constam como revogados na fonte.'),
(92,'','Comunicação dos coeficientes de participação nos fundos','O Tribunal de Contas da União comunicará ao Banco do Brasil S.A. os coeficientes individuais de participação nos fundos previstos no art. 159, inciso I, alíneas a, b e d, da Constituição Federal que prevalecerão no exercício subsequente, até o último dia útil do mês de março de cada exercício financeiro, para cada Estado e para o Distrito Federal (inciso I), e até o último dia útil de cada exercício financeiro, para cada Município (inciso II). O parágrafo único dispõe que far-se-á nova comunicação sempre que houver, transcorrido o prazo fixado no inciso I, a criação de novo Estado a ser implantado no exercício subsequente. O texto traz as anotações "Produção de efeito" e "Vide Lei Complementar nº 143, de 2013".'),
(96,'','Conceito de legislação tributária','A expressão "legislação tributária" compreende as leis, os tratados e as convenções internacionais, os decretos e as normas complementares que versem, no todo ou em parte, sobre tributos e relações jurídicas a eles pertinentes.'),
(97,'','Reserva de lei em matéria tributária','Somente a lei pode estabelecer a instituição de tributos, ou a sua extinção (inciso I); a majoração de tributos, ou sua redução, ressalvado o disposto nos arts. 21, 26, 39, 57 e 65 (inciso II); a definição do fato gerador da obrigação tributária principal, ressalvado o disposto no inciso I do § 3º do art. 52, e do seu sujeito passivo (inciso III); a fixação de alíquota do tributo e da sua base de cálculo, ressalvado o disposto nos arts. 21, 26, 39, 57 e 65 (inciso IV); a cominação de penalidades para as ações ou omissões contrárias a seus dispositivos, ou para outras infrações nela definidas (inciso V); e as hipóteses de exclusão, suspensão e extinção de créditos tributários, ou de dispensa ou redução de penalidades (inciso VI). O § 1º equipara à majoração do tributo a modificação da sua base de cálculo que importe em torná-lo mais oneroso. O § 2º dispõe que não constitui majoração de tributo, para os fins do inciso II, a atualização do valor monetário da respectiva base de cálculo.'),
(98,'','Tratados e convenções internacionais em matéria tributária','Os tratados e as convenções internacionais revogam ou modificam a legislação tributária interna, e serão observados pela que lhes sobrevenha.'),
(99,'','Decretos em matéria tributária','O conteúdo e o alcance dos decretos restringem-se aos das leis em função das quais sejam expedidos, determinados com observância das regras de interpretação estabelecidas no CTN.'),
(100,'','Normas complementares','São normas complementares das leis, dos tratados e das convenções internacionais e dos decretos os atos normativos expedidos pelas autoridades administrativas (inciso I); as decisões dos órgãos singulares ou coletivos de jurisdição administrativa, a que a lei atribua eficácia normativa (inciso II); as práticas reiteradamente observadas pelas autoridades administrativas (inciso III); e os convênios que entre si celebrem a União, os Estados, o Distrito Federal e os Municípios (inciso IV). O parágrafo único dispõe que a observância dessas normas exclui a imposição de penalidades, a cobrança de juros de mora e a atualização do valor monetário da base de cálculo do tributo.')
) as v(n,t,c,a)
where l.codigo='ctn' and l.numero=v.n and coalesce(l.titulo,'')=v.t and l.paragrafo is null and l.inciso is null and l.vigente;
